`, "",{"version":3,"sources":["webpack://./src/酒馆助手/梦境创客/ui/components/session/SessionWorkbench.vue"],"names":[],"mappings":"AAwHA,uCACE,sBAAuB,CACvB,yCAA0C,CAC1C,iBAAkB,CAClB,sBACF,CACA,+CACE,cACF","sourcesContent":["<template>\n  <section\n    ref=\"workbenchRoot\"\n    class=\"dca-workbench\"\n    :class=\"{ 'sidebar-collapsed': sidebarCollapsed, 'is-narrow': workbenchWidth < 646 }\"\n    :style=\"{ '--dca-sidebar-width': `${Math.min(sidebarWidth, Math.max(320, workbenchWidth - 326))}px` }\"\n  >\n    <div class=\"dca-session-panel\">\n      <SessionToolbar :sidebar-collapsed=\"sidebarCollapsed\" @toggle-sidebar=\"toggleSidebar\" />\n      <details v-if=\"state.active?.warnings.length\" class=\"dca-session-warnings\">\n        <summary>会话提示（{{ state.active.warnings.length }}）</summary>\n        <ul>\n          <li v-for=\"warning in state.active.warnings\" :key=\"warning\">{{ warning }}</li>\n        </ul>\n      </details>\n      <SessionTimeline @open-diff=\"openDiff\" />\n      <div v-if=\"state.activeSessionAccess === 'readonly-history'\" class=\"dca-readonly-composer\">\n        <i class=\"fa-solid fa-lock\" aria-hidden=\"true\"></i>\n        <div>\n          <strong>历史记录只读</strong\n          ><span>{{\n            state.active?.error ||\n            '对应角色卡已不可用。你仍可查看消息、工具过程、操作记录与 Diff，但不能发送或修改内容。'\n          }}</span>\n        </div>\n        <button\n          v-if=\"state.active?.scope === 'global' || state.active?.bindingId === state.currentCharacter?.bindingId\"\n          type=\"button\"\n          :disabled=\"state.busy\"\n          @click=\"retryWorkspace\"\n        >\n          重新加载工作区\n        </button>\n      </div>\n      <SessionComposer v-else />\n    </div>\n    <div\n      v-if=\"!sidebarCollapsed\"\n      class=\"dca-sidebar-resizer\"\n      title=\"拖拽调整侧栏宽度\"\n      @pointerdown=\"beginSidebarResize\"\n    ></div>\n    <SessionSidebar\n      v-if=\"!sidebarCollapsed\"\n      v-model:tab=\"sidebarTab\"\n      :diff-focus=\"diffFocus\"\n      :focus-file-path=\"focusFilePath\"\n      @close=\"sidebarCollapsed = true\"\n    />\n    <OperationReplayDialog />\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from 'vue';\nimport { useElementWidth } from '../../composables/element-width';\nimport { useDreamCardAgent, type SidebarTab } from '../../composables/runtime';\nimport type { OperationDiffFocus } from '../../composables/operation-diff';\nimport { useSidebarResize } from '../../composables/sidebar-resize';\nimport SessionComposer from './SessionComposer.vue';\nimport OperationReplayDialog from './OperationReplayDialog.vue';\nimport SessionTimeline from './SessionTimeline.vue';\nimport SessionToolbar from './SessionToolbar.vue';\nimport SessionSidebar from './sidebar/SessionSidebar.vue';\n\nconst { sidebarFocus, state, runtime, action } = useDreamCardAgent();\n\nasync function retryWorkspace() {\n  const active = state.value.active;\n  if (!active) return;\n  await action(() =>\n    active.scope === 'global' ? runtime.openGlobalSession(active.sessionId) : runtime.openSession(active.sessionId),\n  );\n}\n\nconst sidebarCollapsed = ref(true);\nconst workbenchRoot = ref<HTMLElement>();\nconst workbenchWidth = useElementWidth(workbenchRoot);\nconst sidebarWidth = ref(390);\nconst sidebarTab = ref<SidebarTab>('files');\nconst focusFilePath = ref('');\nconst diffFocus = ref<(OperationDiffFocus & { requestId: number }) | undefined>();\nconst { beginSidebarResize } = useSidebarResize(sidebarWidth);\n\nfunction toggleSidebar() {\n  sidebarCollapsed.value = !sidebarCollapsed.value;\n}\n\nfunction openSidebar(tab: SidebarTab) {\n  sidebarTab.value = tab;\n  sidebarCollapsed.value = false;\n}\n\nfunction openDiff(focus: OperationDiffFocus) {\n  diffFocus.value = { ...focus, requestId: Date.now() };\n  if (window.innerWidth > 720) {\n    sidebarWidth.value = Math.max(sidebarWidth.value, Math.min(680, workbenchWidth.value * (2 / 3)));\n  }\n  openSidebar('diff');\n}\n\n// 其它区域（如 Skill 设置页）请求在侧栏中定位文件。\n// immediate：请求可能在本组件挂载前就已发出（例如从设置页跳转过来）。\nwatch(\n  sidebarFocus,\n  request => {\n    if (!request) return;\n    if (!state.value.active) {\n      sidebarFocus.value = undefined;\n      return;\n    }\n    focusFilePath.value = request.filePath ?? '';\n    openSidebar(request.tab);\n    sidebarFocus.value = undefined;\n  },\n  { immediate: true },\n);\n</script>\n\n<style scoped>\n.dca-session-warnings {\n  padding: 0.5rem 0.75rem;\n  border-bottom: 1px solid var(--dca-border);\n  font-size: 0.85rem;\n  overflow-wrap: anywhere;\n}\n.dca-session-warnings summary {\n  cursor: pointer;\n}\n</style>\n\n<style lang=\"scss\">\n.dca-workbench {\n  position: relative;\n  display: grid;\n  height: 100%;\n  min-height: 0;\n  grid-template-columns: minmax(0, 1fr) 6px minmax(20rem, var(--dca-sidebar-width));\n}\n\n.dca-workbench.sidebar-collapsed {\n  grid-template-columns: minmax(0, 1fr);\n}\n\n.dca-session-panel {\n  display: flex;\n  min-width: 0;\n  min-height: 0;\n  flex-direction: column;\n}\n\n.dca-readonly-composer {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 0.75rem;\n  margin: 0.7rem;\n  border: 1px solid color-mix(in srgb, var(--dca-info) 28%, transparent);\n  border-radius: 0.75rem;\n  padding: 0.75rem 0.9rem;\n  background: color-mix(in srgb, var(--dca-info-soft) 55%, transparent);\n  color: var(--dca-text-muted);\n}\n.dca-readonly-composer > i {\n  color: var(--dca-info);\n}\n.dca-readonly-composer > div {\n  display: flex;\n  flex-direction: column;\n}\n.dca-readonly-composer strong {\n  color: var(--dca-text);\n  font-size: 0.82rem;\n}\n.dca-readonly-composer span {\n  font-size: 0.72rem;\n}\n\n.dca-sidebar-resizer {\n  position: relative;\n  min-width: 6px;\n  background: var(--dca-surface);\n  cursor: col-resize;\n}\n\n.dca-sidebar-resizer::after {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: 2px;\n  width: 1px;\n  background: var(--dca-border);\n  content: '';\n  transition:\n    left var(--dca-motion-fast) ease,\n    width var(--dca-motion-fast) ease,\n    background var(--dca-motion-fast) ease;\n}\n\n.dca-sidebar-resizer:hover::after,\n.dca-resizing-sidebar .dca-sidebar-resizer::after {\n  left: 1px;\n  width: 3px;\n  background: var(--dca-accent);\n}\n\n.dca-resizing-sidebar {\n  cursor: col-resize !important;\n  user-select: none !important;\n}\n\n.dca-workbench.is-narrow:not(.sidebar-collapsed) {\n  display: block;\n  > .dca-session-panel {\n    height: 100%;\n  }\n  > .dca-session-sidebar {\n    position: absolute;\n    z-index: 30;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    border-left: 0;\n    background: var(--dca-surface);\n    box-shadow: var(--dca-shadow-3);\n  }\n  > .dca-sidebar-resizer {\n    display: none;\n  }\n}\n@media (max-width: 720px) {\n  .dca-workbench:not(.sidebar-collapsed) {\n    display: block;\n  }\n\n  .dca-workbench:not(.sidebar-collapsed) > .dca-session-panel {\n    height: 100%;\n  }\n\n  .dca-workbench:not(.sidebar-collapsed) > .dca-session-sidebar {\n    position: absolute;\n    z-index: 30;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    border-left: 0;\n    background: var(--dca-surface);\n    box-shadow: var(--dca-shadow-3);\n  }\n\n  .dca-sidebar-resizer {\n    display: none;\n  }\n}\n</style>\n"],"sourceRoot":""}]);
